PHASE 3 — create `scripts/build_puzzle_sql.mjs`:
```js
import { createReadStream, createWriteStream, mkdirSync } from 'node:fs';
import { createInterface } from 'node:readline';
import { join } from 'node:path';

const CSV = process.argv[2] || `${process.env.HOME}/Downloads/lichess_db_puzzle.csv`;
const OUT = process.argv[3] || `${process.env.HOME}/.cache/e4_puzzle_sql`;
const B62 = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz';
const STMT_BYTES = 90000;
const FILE_BYTES = 40 * 1024 * 1024;

function point_id(s) {
	let n = 0;
	for (const ch of s) n = n * 62 + B62.indexOf(ch);
	return n;
}

function q(s) {
	return `'${s.replaceAll("'", "''")}'`;
}

function writer(prefix) {
	let file = 0;
	let stream = null;
	let file_len = 0;
	let values = [];
	let stmt_len = 0;
	const head = prefix === 'puz'
		? 'insert or replace into puz (id,f,m,r,v,w,t) values '
		: 'insert or replace into pt (g,p) values ';

	const open = () => {
		stream = createWriteStream(join(OUT, `${prefix}_${String(file).padStart(3, '0')}.sql`));
		file_len = 0;
	};
	const flush = () => {
		if (!values.length) return;
		if (!stream) open();
		const line = `${head}${values.join(',')};\n`;
		stream.write(line);
		file_len += line.length;
		values = [];
		stmt_len = 0;
		if (file_len >= FILE_BYTES) {
			stream.end();
			stream = null;
			file++;
		}
	};

	return {
		push(v) {
			if (stmt_len + v.length > STMT_BYTES) flush();
			values.push(v);
			stmt_len += v.length + 1;
		},
		end() {
			flush();
			if (stream) stream.end();
		}
	};
}

mkdirSync(OUT, { recursive: true });
const puz = writer('puz');
const pt = writer('pt');

let n = 0;
const started = Date.now();
const rl = createInterface({ input: createReadStream(CSV), crlfDelay: Infinity });
for await (const line of rl) {
	if (!line || line.startsWith('PuzzleId,')) continue;
	const c = line.split(',');
	const id = point_id(c[0]);
	const tags = [...c[7].split(' '), ...(c[9] ? c[9].split(' ') : [])].filter(Boolean);
	const w = c[1].split(' ')[1] === 'w' ? 0 : 1;
	puz.push(`(${id},${q(c[1])},${q(c[2])},${+c[3]},${+c[5]},${w},${q(` ${tags.join(' ')} `)})`);
	for (const t of tags) pt.push(`(${q(t)},${id})`);
	if (++n % 500000 === 0) console.log(`${n} rows | ${Math.round(n / ((Date.now() - started) / 1000))}/s`);
}
puz.end();
pt.end();
console.log(`done: ${n} rows -> ${OUT}`);
```
Notes that matter: `insert or replace` makes re-running an import idempotent (the id is deterministic). `STMT_BYTES` of 90,000 keeps every statement under D1's 100,000-byte cap with headroom for the INSERT prefix. `FILE_BYTES` of 40 MB keeps each file far under the 5 GB import cap and makes a failed chunk cheap to retry. Output goes to `~/.cache/e4_puzzle_sql` — outside the repo, so nothing needs gitignoring.

PHASE 4 — `pnpm test scripts/build_puzzle_sql.test.ts` green, `pnpm test` shows no NEW failures, `pnpm type-check` green.

Then commit scoped to sql_dump_builder and push.

