CURRENT STATE. `src/lib/server/puzzles.ts` opens a `QdrantClient` from `$env/static/private` at module scope and calls `scroll('puz', { filter, limit, offset })`. `src/lib/util/chat/tools/find_puzzles.ts` exports a ready-made `tool({...})` object that closes over nothing. `src/routes/chess/learn/chat/+server.ts:90` passes it as `tools: { get_fen, evaluate_position, find_puzzles }`. `src/routes/api/puzzles/+server.ts:6` destructures only `{ request }`. None of them can see a binding.

PHASE 1 — replace `src/lib/server/puzzles.test.ts` wholesale. Its current qdrant mock (`vi.mock('@qdrant/js-client-rest')`, rows as `[id, payload]`, `vi.mock('$env/static/private')`) is dead. New file:
```ts
import { describe, expect, it } from 'vitest';
import { search_puzzles } from './puzzles';

type Call = { sql: string; args: unknown[] };

function fake_db(rows: Record<string, unknown>[] = []) {
	const calls: Call[] = [];
	const db = {
		prepare(sql: string) {
			const call: Call = { sql, args: [] };
			const stmt = {
				bind(...args: unknown[]) {
					call.args = args;
					calls.push(call);
					return stmt;
				},
				async all() {
					return { results: rows };
				}
			};
			return stmt;
		}
	} as unknown as D1Database;
	return { db, calls };
}

const ROW = {
	id: 13,
	f: '5rk1/1p3ppp/pq3b2/8/8/1P1Q1N2/P4PPP/3R2K1 w - - 2 27',
	m: 'd3d6 f8d8 d6d8 f6d8',
	r: 1579,
	v: 96,
	t: ' advantage endgame short '
};

describe('search_puzzles', () => {
	it('seeks pt on the rarest tag and filters the rest with padded LIKE', async () => {
		const { db, calls } = fake_db();
		await search_puzzles(db, { t: ['endgame', 'underPromotion'] });
		expect(calls[0].sql).toContain('from pt join puz p on p.id=pt.p');
		expect(calls[0].args[0]).toBe('underPromotion');
		expect(calls[0].args).toContain('% endgame %');
	});

	it('turns any tags into an OR of padded LIKEs', async () => {
		const { db, calls } = fake_db();
		await search_puzzles(db, { t: ['fork'], any: ['pin', 'skewer'] });
		expect(calls[0].sql).toContain('(p.t like ? or p.t like ?)');
		expect(calls[0].args).toContain('% pin %');
		expect(calls[0].args).toContain('% skewer %');
	});

	it('maps rating band tags to a rating range, not a pt seek', async () => {
		const { db, calls } = fake_db();
		await search_puzzles(db, { t: ['fork', 'rating_easy'] });
		expect(calls[0].args[0]).toBe('fork');
		expect(calls[0].sql).not.toContain('rating_easy');
		expect(calls[0].args).toContain(1200);
		expect(calls[0].args).toContain(1499);
	});

	it('maps solve_white and popular to column predicates', async () => {
		const { db, calls } = fake_db();
		await search_puzzles(db, { t: ['solve_white', 'popular'] });
		expect(calls[0].sql).toContain('p.w = ?');
		expect(calls[0].sql).toContain('p.v >= ?');
		expect(calls[0].args).toContain(1);
		expect(calls[0].args).toContain(90);
	});

	it('scans puz directly when no real tag is given', async () => {
		const { db, calls } = fake_db();
		await search_puzzles(db, { r_min: 1500 });
		expect(calls[0].sql).toContain('from puz p where p.id>?');
		expect(calls[0].sql).not.toContain('join pt');
	});

	it('clamps the result count to 1..30 with a default of 5', async () => {
		for (const [n, want] of [[500, 30], [0, 1], [undefined, 5]] as const) {
			const { db, calls } = fake_db();
			await search_puzzles(db, n === undefined ? {} : { n });
			expect(calls[0].args.at(-1)).toBe(want);
		}
	});

	it('starts each search at a different random offset below the id ceiling', async () => {
		const offsets = new Set<unknown>();
		for (let i = 0; i < 8; i++) {
			const { db, calls } = fake_db();
			await search_puzzles(db, {});
			const o = calls[0].args[0] as number;
			expect(o).toBeLessThan(916132592);
			offsets.add(o);
		}
		expect(offsets.size).toBeGreaterThan(1);
	});

	it('honours an explicit after offset and does not wrap', async () => {
		const { db, calls } = fake_db();
		await search_puzzles(db, { after: 1234 });
		expect(calls.length).toBe(1);
		expect(calls[0].args[0]).toBe(1234);
	});

	it('wraps to zero when the random offset lands past the last match', async () => {
		const { db, calls } = fake_db([ROW]);
		await search_puzzles(db, { n: 3 });
		expect(calls.length).toBe(2);
		expect(calls[1].args[0]).toBe(0);
	});

	it('returns the position after the blunder and re-encodes the puzzle id', async () => {
		const { db } = fake_db([ROW]);
		const [pz] = await search_puzzles(db, { after: 0, n: 1 });
		expect(pz.f).toBe('5rk1/1p3ppp/pq1Q1b2/8/8/1P3N2/P4PPP/3R2K1 b - - 3 27');
		expect(pz.m).toBe('f8d8 d6d8 f6d8');
		expect(pz.p).toBe('0000D');
		expect(pz.t).toEqual(['advantage', 'endgame', 'short']);
	});
});
```
That expected FEN is verified, not guessed: `d3d6` is a QUIET queen move, not a capture — the black queen stays on b6, hence `pq1Q1b2`.

