PHASE 3 — implement.
(a) Replace `src/lib/server/puzzles.ts` entirely:
```ts
import { Chess } from 'chess.js';
import { PUZZLE_TAG_COUNTS } from '$lib/types/puzzle';
import type { Puzzle, PuzzleQuery } from '$lib/types/puzzle';

const MAX_ID = 916132592;
const B62 = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz';
const RATING_BANDS: Record<string, [number, number]> = {
	rating_beginner: [0, 1199],
	rating_easy: [1200, 1499],
	rating_intermediate: [1500, 1799],
	rating_advanced: [1800, 2099],
	rating_expert: [2100, 2399],
	rating_master: [2400, 9999]
};

type Row = { id: number; f: string; m: string; r: number; v: number; t: string };

export async function search_puzzles(db: D1Database, query: PuzzleQuery): Promise<Puzzle[]> {
	let r_min = query.r_min;
	let r_max = query.r_max;
	let v_min = query.v_min ?? 80;
	let w: number | null = null;
	const tags: string[] = [];

	for (const raw of query.t ?? []) {
		const band = RATING_BANDS[raw];
		if (band) {
			r_min = Math.max(r_min ?? 0, band[0]);
			r_max = Math.min(r_max ?? 9999, band[1]);
		} else if (raw === 'solve_white') w = 1;
		else if (raw === 'solve_black') w = 0;
		else if (raw === 'popular') v_min = Math.max(v_min, 90);
		else tags.push(raw);
	}

	const any = (query.any ?? []).filter((a) => !(a in RATING_BANDS) && !['solve_white', 'solve_black', 'popular'].includes(a));
	const rarity = (t: string) => PUZZLE_TAG_COUNTS[t] ?? 1000;
	const seek = tags.length ? tags.reduce((a, b) => (rarity(a) <= rarity(b) ? a : b)) : null;
	const limit = Math.min(Math.max(query.n ?? 5, 1), 30);

	const rows = await page(db, seek, tags, any, r_min, r_max, v_min, w, limit, query.after ?? Math.floor(Math.random() * MAX_ID));
	// a random start near the top of the id space can run out of matches — wrap to the
	// beginning so a narrow filter still fills the page.
	if (rows.length < limit && query.after == null) {
		const seen = new Set(rows.map((r) => r.id));
		for (const r of await page(db, seek, tags, any, r_min, r_max, v_min, w, limit, 0)) {
			if (rows.length >= limit) break;
			if (!seen.has(r.id)) rows.push(r);
		}
	}

	return rows.map((row) => {
		const moves = row.m.split(' ');
		return {
			p: encode_id(row.id),
			f: solve_fen(row.f, moves[0]),
			m: moves.slice(1).join(' '),
			r: row.r,
			v: row.v,
			t: row.t.trim().split(' ').filter(Boolean)
		};
	});
}

async function page(
	db: D1Database,
	seek: string | null,
	tags: string[],
	any: string[],
	r_min: number | undefined,
	r_max: number | undefined,
	v_min: number,
	w: number | null,
	limit: number,
	from: number
): Promise<Row[]> {
	const args: unknown[] = [];
	let sql: string;
	if (seek) {
		sql = 'select p.id,p.f,p.m,p.r,p.v,p.t from pt join puz p on p.id=pt.p where pt.g=? and pt.p>?';
		args.push(seek, from);
	} else {
		sql = 'select p.id,p.f,p.m,p.r,p.v,p.t from puz p where p.id>?';
		args.push(from);
	}
	for (const t of tags) {
		if (t === seek) continue;
		sql += ' and p.t like ?';
		args.push(`% ${t} %`);
	}
	if (any.length) {
		sql += ` and (${any.map(() => 'p.t like ?').join(' or ')})`;
		for (const a of any) args.push(`% ${a} %`);
	}
	if (r_min != null) {
		sql += ' and p.r >= ?';
		args.push(r_min);
	}
	if (r_max != null) {
		sql += ' and p.r <= ?';
		args.push(r_max);
	}
	sql += ' and p.v >= ?';
	args.push(v_min);
	if (w != null) {
		sql += ' and p.w = ?';
		args.push(w);
	}
	sql += seek ? ' order by pt.p limit ?' : ' order by p.id limit ?';
	args.push(limit);
	const r = await db.prepare(sql).bind(...args).all<Row>();
	return r.results ?? [];
}

function encode_id(n: number): string {
	let s = '';
	for (let i = 0; i < 5; i++) {
		s = B62[n % 62] + s;
		n = Math.floor(n / 62);
	}
	return s;
}

// A lichess puzzle's stored FEN is the position *before* the opponent's blunder. The first
// stored move is that blunder; the user solves from the position after it.
function solve_fen(fen: string, first: string): string {
	const c = new Chess(fen);
	c.move({ from: first.slice(0, 2), to: first.slice(2, 4), promotion: first.slice(4) || undefined });
	return c.fen();
}
```
D1 allows max 100 bound parameters per query — the worst realistic query binds well under 20, so no guard is needed.
(b) In `src/lib/types/puzzle.ts` delete `u: string;` from the `Puzzle` type (line 7). The lichess GameUrl is no longer stored; it was 240 MB of never-read text. Nothing reads `Puzzle.u` — confirm with `grep -rn "\.u\b" src/lib/util/chat src/routes/api/puzzles` before deleting.
(c) Turn `src/lib/util/chat/tools/find_puzzles.ts` into a factory. Keep `puzzle_input` exported unchanged (`src/routes/api/puzzles/+server.ts:4` imports it). Replace the `export const find_puzzles = tool({...})` block with:
```ts
export function make_find_puzzles(db: D1Database | undefined) {
	return tool({
		description: PUZZLE_TOOL_DESCRIPTION,
		inputSchema: puzzle_input,
		execute: async (q) => {
			if (!db) return { puzzles: [], error: 'Puzzle database is not available.' };
			try {
				const puzzles = await search_puzzles(db, q);
				if (!puzzles.length) return { puzzles: [], error: 'No puzzles matched. Try fewer tags in "t".' };
				return { puzzles };
			} catch (e) {
				return { puzzles: [], error: e instanceof Error ? e.message : String(e) };
			}
		}
